preConditionHook:
// The BOOK form of ProfitProtector (Davey, exit #9), kept as a separate rule
// for exact testing against the book: `>=` on the floor where ProfitProtector
// uses `>`, and a DIVISION open/max < ratio where ProfitProtector multiplies
// ratio*max -- the two round differently and can land on opposite sides of
// the comparison. The nested-if structure is the book's: the division is only
// evaluated once the floor is reached, so MaxPositionProfit is never 0 there.
ratioBelow = false;
if (el_ge(ctx.MaxPositionProfit(), profitFloor)) {
    if (el_lt(ctx.OpenPositionProfit() / ctx.MaxPositionProfit(), keepRatio)) ratioBelow = true;
}
